        {
            /* Check for output buffer overflow before each write */
            if (output_index >= output_size)
            {
                return -1;
            }

            output_buffer[output_index] = value;
            output_index++;
        }
    }

    /* If there are leftover bytes (incomplete encoding unit), treat as error */
    if (input_index < compressed_len)
    {
        return -1;
    }

    /* If no units were processed, return 0 */
    if (output_index == 0)
    {
        return 0;
    }

    return output_index;
}
